/// Readline's code table: the name plus any shift or ctrl the code itself implies.
pub fn code_name(code: &str) -> (&'static str, bool, bool) {
    let plain = |name| (name, false, false);

    match code {
        "[P" | "OP" | "[11~" | "[[A" => plain("f1"),
        "[Q" | "OQ" | "[12~" | "[[B" => plain("f2"),
        "[R" | "OR" | "[13~" | "[[C" => plain("f3"),
        "[S" | "OS" | "[14~" | "[[D" => plain("f4"),
        "[[E" | "[15~" => plain("f5"),
        "[17~" => plain("f6"),
        "[18~" => plain("f7"),
        "[19~" => plain("f8"),
        "[20~" => plain("f9"),
        "[21~" => plain("f10"),
        "[23~" => plain("f11"),
        "[24~" => plain("f12"),
        "[200~" => plain("paste-start"),
        "[201~" => plain("paste-end"),
        "[A" | "OA" => plain("up"),
        "[B" | "OB" => plain("down"),
        "[C" | "OC" => plain("right"),
        "[D" | "OD" => plain("left"),
        "[E" | "OE" => plain("clear"),
        "[F" | "OF" | "[4~" | "[8~" => plain("end"),
        "[H" | "OH" | "[1~" | "[7~" => plain("home"),
        "[2~" => plain("insert"),
        "[3~" => plain("delete"),
        "[5~" | "[[5~" => plain("pageup"),
        "[6~" | "[[6~" => plain("pagedown"),
        "[a" => ("up", true, false),
        "[b" => ("down", true, false),
        "[c" => ("right", true, false),
        "[d" => ("left", true, false),
        "[e" => ("clear", true, false),
        "[2$" => ("insert", true, false),
        "[3$" => ("delete", true, false),
        "[5$" => ("pageup", true, false),
        "[6$" => ("pagedown", true, false),
        "[7$" => ("home", true, false),
        "[8$" => ("end", true, false),
        "Oa" => ("up", false, true),
        "Ob" => ("down", false, true),
        "Oc" => ("right", false, true),
        "Od" => ("left", false, true),
        "Oe" => ("clear", false, true),
        "[2^" => ("insert", false, true),
        "[3^" => ("delete", false, true),
        "[5^" => ("pageup", false, true),
        "[6^" => ("pagedown", false, true),
        "[7^" => ("home", false, true),
        "[8^" => ("end", false, true),
        "[Z" => ("tab", true, false),
        _ => plain("undefined"),
    }
}
